 Activity manager()throws Exception{ActivityMonitor monitor=m.addMonitor("org.rabochaya.projects.MapLayersActivity",null,false);m.clickDescription("Карты");m.click("Слои карты");Activity a=m.waitForMonitorWithTimeout(monitor,15000);m.removeMonitor(monitor);m.check(a!=null,"map menu opens real composition manager");m.activity=a;m.waitText("Использовать композицию слоёв");return a;}
