 void addCatalog(Object entry)throws Exception{Activity parent=m.activity;ActivityMonitor monitor=m.addMonitor("org.rabochaya.projects.MapCatalogActivity",null,false);m.click("Добавить слой");m.click("Из каталога");m.activity=m.waitForMonitorWithTimeout(monitor,15000);m.removeMonitor(monitor);m.check(m.activity!=null,"layer add opens existing catalog picker");m.waitText("Добавить слой");String group=(String)f(entry,"group"),name=(String)f(f(entry,"source"),"name");if(!m.getTargetContext().getSharedPreferences("catalog-ui",0).getBoolean("expanded_"+group,false))m.clickDescription(group);m.clickDescription(name);m.activity=parent;m.waitText(name);m.check(layers().size()>0,"explicit source selection adds layer");}
 SeekBar seek(View view){if(view instanceof SeekBar)return (SeekBar)view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){SeekBar b=seek(((ViewGroup)view).getChildAt(i));if(b!=null)return b;}return null;}
 void opacity(Object row)throws Exception{String id=(String)f(row,"id");final int[] xy=new int[2];final float[] point=new float[2];m.runOnMainSync(()->{View card=m.activity.getWindow().getDecorView().findViewWithTag(id);SeekBar bar=seek(card);m.check(bar!=null,"layer opacity slider exists");bar.requestRectangleOnScreen(new Rect(0,0,bar.getWidth(),bar.getHeight()),true);});m.waitForIdleSync();m.runOnMainSync(()->{SeekBar bar=seek(m.activity.getWindow().getDecorView().findViewWithTag(id));m.check(bar.isShown()&&v.fullyVisible(bar),"opacity slider physically visible before real touch");bar.getLocationOnScreen(xy);point[0]=xy[0]+bar.getWidth()/2f;point[1]=xy[1]+bar.getHeight()/2f;});long now=SystemClock.uptimeMillis();for(int action:new int[]{MotionEvent.ACTION_DOWN,MotionEvent.ACTION_UP}){MotionEvent e=MotionEvent.obtain(now,SystemClock.uptimeMillis(),action,point[0],point[1],0);m.check(m.getUiAutomation().injectInputEvent(e,true),"real opacity touch event injected");e.recycle();}m.waitForIdleSync();Thread.sleep(400);}
 void fill(Object source,int color)throws Exception{Object cache=m.onlineCache(source);Field field=m.owned("OnlineTiles").getDeclaredField("db");field.setAccessible(true);SQLiteDatabase db=(SQLiteDatabase)field.get(cache);Bitmap image=Bitmap.createBitmap(256,256,Bitmap.Config.ARGB_8888);image.eraseColor(color);ByteArrayOutputStream out=new ByteArrayOutputStream();image.compress(Bitmap.CompressFormat.PNG,100,out);image.recycle();db.beginTransaction();try{for(int x=0;x<4;x++)for(int y=0;y<4;y++){ContentValues row=new ContentValues();row.put("zoom_level",2);row.put("tile_column",x);row.put("tile_row",3-y);row.put("tile_data",out.toByteArray());row.put("expires",System.currentTimeMillis()+86400000L);db.insertWithOnConflict("tiles",null,row,SQLiteDatabase.CONFLICT_REPLACE);}db.setTransactionSuccessful();}finally{db.endTransaction();m.call(cache,"close",new Class[]{});}}
 void pixel(int expected)throws Exception{long end=System.currentTimeMillis()+15000;int actual=0;while(System.currentTimeMillis()<end){final int[] color={0};m.runOnMainSync(()->{try{View view=(View)m.map();if(view.getWidth()>80&&view.getHeight()>80){Bitmap b=Bitmap.createBitmap(view.getWidth(),view.getHeight(),Bitmap.Config.ARGB_8888);view.draw(new Canvas(b));color[0]=b.getPixel(35,45);b.recycle();}}catch(Exception e){throw new RuntimeException(e);}});actual=color[0];if(Math.abs(Color.red(actual)-Color.red(expected))<=3&&Math.abs(Color.green(actual)-Color.green(expected))<=3&&Math.abs(Color.blue(actual)-Color.blue(expected))<=3){m.check(true,"actual renderer pixel matches composition order/opacity "+Integer.toHexString(actual));return;}Thread.sleep(150);}throw new AssertionError("composition pixel actual="+Integer.toHexString(actual)+" expected="+Integer.toHexString(expected));}
 int blend(int below,int above,int opacity){int a=Math.round(opacity*255f/100f);return Color.rgb((Color.red(above)*a+Color.red(below)*(255-a)+127)/255,(Color.green(above)*a+Color.green(below)*(255-a)+127)/255,(Color.blue(above)*a+Color.blue(below)*(255-a)+127)/255);}
 void capture(String tag)throws Exception{m.capture("mvisual-layers-"+tag);Bundle b=new Bundle();b.putString("stream","MAP_LAYERS_VISUAL "+tag+"\n");m.sendStatus(0,b);}
 void unchanged(Object store,long id,byte[] xml,Map<String,byte[]> assets)throws Exception{m.check(Arrays.equals(xml,r.xml(r.load(store,id))),"layer actions never rewrite KML");r.sameAssets(r.load(store,id),assets);}
 void cacheRetained(Object source,int expected)throws Exception{Object cache=m.onlineCache(source);try{long[] stats=(long[])m.call(cache,"stats",new Class[]{});m.check(stats[0]>=16,"removing/hiding a layer preserves its source cache");Bitmap tile=m.onlineTile(cache,2,1,1,false);m.check(tile!=null&&tile.getPixel(50,50)==expected,"source tile payload unchanged");if(tile!=null)tile.recycle();}finally{m.call(cache,"close",new Class[]{});}}
 void run(boolean reopen)throws Exception{m.installTileFixture();if(reopen){reopen();return;}Context context=m.getTargetContext();context.getSharedPreferences("online-map",0).edit().putBoolean("network",false).putString("name","QA_LAYER_CUSTOM").putString("template","https://tiles.example.org/layers-custom/{z}/{x}/{y}.png").putString("attribution","QA local fixture").putInt("min",0).putInt("max",6).putBoolean("downloads",true).commit();Object store=m.storeClass.getConstructor(Context.class).newInstance(context);long id=-1,other=-1;Activity main=null;boolean keep=false;try{id=new GeometryConfirmationChecks(m).fixture(store,false);other=new GeometryConfirmationChecks(m).fixture(store,false);Object doc=r.load(store,id);byte[] xml=r.xml(doc),otherXml=r.xml(r.load(store,other));Map<String,byte[]> assets=new HashMap<>(m.assets(doc));File local=m.tiles("local_basemap_"+id+".mbtiles",true,true);byte[] localHash=m.hash(local);Object a=entry(0),b=entry(1),sa=f(a,"source"),sb=f(b,"source");String ka=(String)f(a,"key"),kb=(String)f(b,"key");fill(sa,Color.RED);fill(sb,Color.BLUE);main=main(id);manager();m.check(layers().size()==1&&"local".equals(f(layers().get(0),"kind"))&&!(Boolean)f(snapshot(),"enabled"),"initial manager reuses existing MBTiles without changing active settings");m.click("Убрать");m.click("Отмена");m.check(layers().size()==1&&!(Boolean)f(snapshot(),"enabled")&&context.getSharedPreferences("map-compositions",0).getAll().isEmpty(),"Cancel remove leaves composition settings untouched");m.click("Убрать");m.click("Убрать");m.check(layers().isEmpty()&&local.isFile()&&Arrays.equals(localHash,m.hash(local)),"explicit remove drops only row and keeps exact MBTiles file");m.click("Добавить слой");m.click("Настроенный XYZ-источник");m.check(layers().size()==1&&"custom".equals(f(layers().get(0),"kind"))&&"https://tiles.example.org/layers-custom/{z}/{x}/{y}.png".equals(f(layers().get(0),"template")),"explicit add reuses configured XYZ source without duplicating its editor");m.click("Убрать");m.click("Убрать");m.check(layers().isEmpty(),"explicit custom removal changes only composition");addCatalog(a);addCatalog(b);opacity(layer(kb));int alpha=(Integer)f(layer(kb),"opacity");m.check(alpha>0&&alpha<100,"real slider applies partial opacity");m.check(context.getSharedPreferences("online-map",0).getString("catalog","").isEmpty()&&!context.getSharedPreferences("online-map",0).getBoolean("network",true),"catalog layer-pick preserves prior single-map/network choice");capture("manager");closeManager(main);m.setViewport(.5,.5,2);pixel(blend(Color.RED,Color.BLUE,alpha));capture("composed");unchanged(store,id,xml,assets);
 manager();m.click("Ниже");m.check(((String)f(layers().get(0),"key")).equals(kb),"explicit lower changes bottom-to-top order");closeManager(main);pixel(Color.RED);capture("reordered");manager();m.click("Показывать слой");m.check(!(Boolean)f(layer(ka),"visible"),"explicit visibility disables top layer");addCatalog(a);m.click("Убрать");m.click("Убрать");m.check(layers().size()==2&&!(Boolean)f(layer(ka),"visible"),"removing duplicate source keeps original hidden row");closeManager(main);pixel(blend(0xff253020,Color.BLUE,alpha));m.setViewport(.5,.5,3);Thread.sleep(800);m.check(m.requests.get()==0,"uncached composition zoom respects disabled network");m.setViewport(.5,.5,2);pixel(blend(0xff253020,Color.BLUE,alpha));manager();byte[] beforeSuspend=encoded(model());m.click("Использовать композицию слоёв");m.check(!(Boolean)f(snapshot(),"enabled")&&Arrays.equals(beforeSuspend,encoded(model())),"suspending composition preserves exact saved layer set");m.click("К карте");m.activity=main;m.waitText("Локальная карта MBTiles");manager();m.click("Использовать композицию слоёв");m.check((Boolean)f(snapshot(),"enabled")&&Arrays.equals(beforeSuspend,encoded(model())),"explicit re-enable restores saved set without rebuilding layer identities");closeManager(main);pixel(blend(0xff253020,Color.BLUE,alpha));capture("final");cacheRetained(sa,Color.RED);cacheRetained(sb,Color.BLUE);unchanged(store,id,xml,assets);m.check(Arrays.equals(otherXml,r.xml(r.load(store,other)))&&!(Boolean)f(stored(other),"enabled"),"composition isolated from another project");m.check(Arrays.equals(localHash,m.hash(local)),"all composition actions retain exact local file");Object saved=stored(id);JSONObject payloads=new JSONObject();for(Map.Entry<String,byte[]> e:assets.entrySet())payloads.put(e.getKey(),android.util.Base64.encodeToString(e.getValue(),android.util.Base64.NO_WRAP));context.getSharedPreferences("qa_layers",0).edit().putLong("project",id).putLong("other",other).putString("xml",android.util.Base64.encodeToString(xml,android.util.Base64.NO_WRAP)).putString("assets",payloads.toString()).putString("composition",android.util.Base64.encodeToString(encoded(f(saved,"composition")),android.util.Base64.NO_WRAP)).putString("localhash",android.util.Base64.encodeToString(localHash,android.util.Base64.NO_WRAP)).putInt("opacity",alpha).commit();keep=true;}finally{v.finish();if(main!=null){m.activity=main;v.finish();}if(!keep){if(id>0)m.call(store,"remove",new Class[]{long.class},id);if(other>0)m.call(store,"remove",new Class[]{long.class},other);}m.call(store,"close",new Class[]{});}}
 void reopen()throws Exception{Context context=m.getTargetContext();android.content.SharedPreferences p=context.getSharedPreferences("qa_layers",0);long id=p.getLong("project",-1),other=p.getLong("other",-1);m.check(id>0&&other>0,"layers handoff survived actual force-stop");Object store=m.storeClass.getConstructor(Context.class).newInstance(context);Activity main=null;try{byte[] xml=android.util.Base64.decode(p.getString("xml",""),android.util.Base64.NO_WRAP);JSONObject j=new JSONObject(p.getString("assets","{}"));Map<String,byte[]> assets=new HashMap<>();for(Iterator<String> keys=j.keys();keys.hasNext();){String k=keys.next();assets.put(k,android.util.Base64.decode(j.getString(k),android.util.Base64.NO_WRAP));}Object saved=stored(id);m.check((Boolean)f(saved,"enabled")&&Arrays.equals(encoded(f(saved,"composition")),android.util.Base64.decode(p.getString("composition",""),android.util.Base64.NO_WRAP)),"exact source/order/visible/opacity/ids restore after process restart");main=main(id);pixel(blend(0xff253020,Color.BLUE,p.getInt("opacity",0)));capture("restarted");m.check(m.requests.get()==0,"cold process uses only saved tile cache");manager();m.check(layers().size()==2,"manager restores stored composition");m.check(!(Boolean)f(layers().get(1),"visible")&&(Integer)f(layers().get(0),"opacity")==p.getInt("opacity",0),"manager controls restore hidden flag and opacity/order");capture("restarted-manager");unchanged(store,id,xml,assets);m.check(Arrays.equals(m.hash(new File(context.getFilesDir(),"local_basemap_"+id+".mbtiles")),android.util.Base64.decode(p.getString("localhash",""),android.util.Base64.NO_WRAP)),"restart retains imported MBTiles");m.check(!(Boolean)f(stored(other),"enabled"),"other project remains outside composition after restart");}finally{v.finish();if(main!=null){m.activity=main;v.finish();}m.call(store,"remove",new Class[]{long.class},id);m.call(store,"remove",new Class[]{long.class},other);m.staticCall("LocalMapActivity","cleanupDeletedProject",new Class[]{Context.class,long.class},context,id);m.staticCall("LocalMapActivity","cleanupDeletedProject",new Class[]{Context.class,long.class},context,other);m.call(store,"close",new Class[]{});}}
